#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int grid[2005][2005];
long long prefix[2006][2006];
long long ans[10];

int main() {
    int H, W, N;
    scanf("%d %d %d", &H, &W, &N);

    memset(grid, 0, sizeof(grid));

    for (int i = 0; i < N; i++) {
        int r, c;
        scanf("%d %d", &r, &c);
        r--; c--;  // 0-indexed
        grid[r][c] = 1;
    }

    // Build prefix sum
    for (int i = 0; i <= H; i++) prefix[i][0] = 0;
    for (int j = 0; j <= W; j++) prefix[0][j] = 0;

    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            prefix[i][j] = grid[i-1][j-1] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1];
        }
    }

    memset(ans, 0, sizeof(ans));

    // For each 3x3 subrectangle
    for (int r = 0; r + 3 <= H; r++) {
        for (int c = 0; c + 3 <= W; c++) {
            // Rectangle from (r, c) to (r+2, c+2)
            int count = prefix[r+3][c+3] - prefix[r][c+3] - prefix[r+3][c] + prefix[r][c];
            if (count >= 0 && count <= 9) {
                ans[count]++;
            }
        }
    }

    for (int j = 0; j <= 9; j++) {
        printf("%lld\n", ans[j]);
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    int H, W, N;
    scanf("%d %d %d", &H, &W, &N);

    // Count of black cells in each possible 3x3 subgrid
    int count[2000][2000] = {0};
    // Result array for j = 0..9
    long long res[10] = {0};

    // Total number of 3x3 subgrids
    long long total = (long long)(H - 2) * (W - 2);

    for (int i = 0; i < N; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--; b--; // zero-index

        // This black cell affects all 3x3 subgrids
        // whose top-left corner is in rows [a-2, a] and cols [b-2, b]
        for (int r = a - 2; r <= a; r++) {
            if (r < 0 || r + 2 >= H) continue;
            for (int c = b - 2; c <= b; c++) {
                if (c < 0 || c + 2 >= W) continue;
                int old = count[r][c];
                count[r][c]++;
                int new = count[r][c];
                // Update counts for j=old and j=new if they are in 0..9
                if (old >= 0 && old <= 9) res[old]--;
                if (new >= 0 && new <= 9) res[new]++;
            }
        }
    }

    // For subgrids that were never touched, they have 0 black cells.
    // We need to add them to res[0].
    // We can compute how many subgrids were updated and subtract from total.
    long long updated = 0;
    for (int r = 0; r + 2 < H; r++) {
        for (int c = 0; c + 2 < W; c++) {
            if (count[r][c] > 0) updated++;
        }
    }
    res[0] += (total - updated);

    for (int j = 0; j <= 9; j++) {
        printf("%lld\n", res[j]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int x, y;
} Cell;

static int cmp_cell(const void *a, const void *b) {
    const Cell *p = (const Cell *)a;
    const Cell *q = (const Cell *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

int main(void) {
    ll H, W;
    int N;
    if (scanf("%lld %lld %d", &H, &W, &N) != 3) return 0;

    Cell *cand = (Cell *)malloc(sizeof(Cell) * (ll)N * 9);
    int m = 0;

    for (int i = 0; i < N; i++) {
        ll a, b;
        scanf("%lld %lld", &a, &b);

        for (ll dx = -2; dx <= 0; dx++) {
            for (ll dy = -2; dy <= 0; dy++) {
                ll x = a + dx;
                ll y = b + dy;
                if (1 <= x && x <= H - 2 && 1 <= y && y <= W - 2) {
                    cand[m].x = (int)x;
                    cand[m].y = (int)y;
                    m++;
                }
            }
        }
    }

    qsort(cand, m, sizeof(Cell), cmp_cell);

    ll ans[10] = {0};

    int i = 0;
    while (i < m) {
        int j = i + 1;
        while (j < m && cand[j].x == cand[i].x && cand[j].y == cand[i].y) j++;
        int cnt = j - i;
        if (1 <= cnt && cnt <= 9) ans[cnt]++;
        i = j;
    }

    ll total = 0;
    if (H >= 3 && W >= 3) total = (H - 2) * (W - 2);
    ll nonzero = 0;
    for (int k = 1; k <= 9; k++) nonzero += ans[k];
    ans[0] = total - nonzero;

    for (int k = 0; k <= 9; k++) {
        printf("%lld\n", ans[k]);
    }

    free(cand);
    return 0;
}

