int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long H, W, N;
    cin >> H >> W >> N;

    map<pair<long long,long long>, int> rect_count;

    for (int i = 0; i < N; i++) {
        long long r, c;
        cin >> r >> c;
        // 1-indexed
        // top-left corner (tr, tc), valid if 1 <= tr <= H-2, 1 <= tc <= W-2
        // cell (r,c) is in rect (tr,tc) if tr <= r <= tr+2, tc <= c <= tc+2
        // so tr in [r-2, r], tc in [c-2, c]
        long long tr_lo = max(1LL, r-2), tr_hi = min(H-2, r);
        long long tc_lo = max(1LL, c-2), tc_hi = min(W-2, c);
        for (long long tr = tr_lo; tr <= tr_hi; tr++) {
            for (long long tc = tc_lo; tc <= tc_hi; tc++) {
                rect_count[{tr, tc}]++;
            }
        }
    }

    long long total_valid = (H >= 3 && W >= 3) ? (H-2)*(W-2) : 0;
    long long ans[10] = {};
    long long nonzero = 0;

    for (auto& [key, cnt] : rect_count) {
        if (cnt >= 1 && cnt <= 9) {
            ans[cnt]++;
            nonzero++;
        }
    }

    ans[0] = total_valid - nonzero;

    for (int j = 0; j <= 9; j++) {
        cout << j << " " << ans[j] << "\n";
    }

    return 0;
}

