import java.io.*;
import java.util.*;

/*
 * Count, for each j = 0..9, how many 3x3 subrectangles contain exactly j black cells.
 *
 * Key idea:
 * A 3x3 subrectangle is identified by its top-left corner (r, c), where
 * 1 <= r <= H-2 and 1 <= c <= W-2.
 *
 * Each black cell affects only the 3x3 subrectangles whose top-left corner lies in:
 * [a-2, a] x [b-2, b]
 * intersected with valid top-left ranges.
 *
 * Since N is small relative to H*W in the intended setting, we only track 3x3 blocks
 * that contain at least one black cell using a hash map:
 *   key(topLeftRow, topLeftCol) -> number of black cells in that 3x3 block
 *
 * Then:
 *   ans[k] = number of tracked blocks with exactly k black cells, for k=1..9
 *   ans[0] = total number of 3x3 blocks - sum(ans[1..9])
 */
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long H = fs.nextLong();
        long W = fs.nextLong();
        int N = fs.nextInt();

        HashMap<Long, Integer> map = new HashMap<>();

        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();

            long r1 = Math.max(1L, a - 2);
            long r2 = Math.min(H - 2, a);
            long c1 = Math.max(1L, b - 2);
            long c2 = Math.min(W - 2, b);

            for (long r = r1; r <= r2; r++) {
                for (long c = c1; c <= c2; c++) {
                    long key = encode(r, c);
                    map.put(key, map.getOrDefault(key, 0) + 1);
                }
            }
        }

        long[] ans = new long[10];
        for (int cnt : map.values()) {
            ans[cnt]++;
        }

        long total = 0;
        if (H >= 3 && W >= 3) total = (H - 2) * (W - 2);

        long nonZero = 0;
        for (int i = 1; i <= 9; i++) nonZero += ans[i];
        ans[0] = total - nonZero;

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= 9; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    // Encodes two positive long coordinates into one long key.
    // H, W are within typical contest constraints, so shifting by 32 bits is safe.
    static long encode(long r, long c) {
        return (r << 32) ^ c;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
